package com.clinic.appointment.controller;import com.clinic.appointment.dto.AppointmentDtos.DoctorLeaveRequest;import com.clinic.appointment.service.AppointmentService;import jakarta.validation.Valid;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/internal/appointments")public class InternalAppointmentController{private final AppointmentService service;private final String key;public InternalAppointmentController(AppointmentService s,@Value("${app.internal-api-key}")String key){service=s;this.key=key;}@PostMapping("/doctor-leave")Map<String,Integer> leave(@RequestHeader("X-Internal-Key")String p,@Valid@RequestBody DoctorLeaveRequest r){if(!key.equals(p))throw new SecurityException("Invalid internal credential");return Map.of("cancelledAppointments",service.doctorLeave(r));}}
